/**
 * Cinejoy webOS - 10-Foot TV Layout Engine
 * Target: webOS 8.5.0 Full HD (1920 x 1080)
 * Google TV Cinema-Grade Aesthetic (#0e1014 dark canvas, #shade dual-gradient scrim, #bgBlur)
 * Enforces strict 5% TV-Safe Area (96px horizontal, 54px vertical)
 * Zero scrollbars, 1080p locked canvas
 */

/* ==========================================================================
   Base Reset & TV Canvas Lock
   ========================================================================== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

html, body {
  width: var(--canvas-width, 1920px);
  height: var(--canvas-height, 1080px);
  min-width: 1920px;
  min-height: 1080px;
  max-width: 1920px;
  max-height: 1080px;
  margin: 0;
  padding: 0;
  background-color: var(--color-bg-base, #0e1014);
  color: var(--color-text-primary, #e8eaed);
  font-family: var(--font-family-base);
  font-size: var(--font-size-body);
  line-height: var(--line-height-normal);
  overflow: hidden;
  user-select: none;
  -webkit-user-select: none;
  scrollbar-width: none;
  -ms-overflow-style: none;
  cursor: default;
}

body::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}

/* ==========================================================================
   Root Application Container
   ========================================================================== */
#app {
  position: relative;
  width: 1920px;
  height: 1080px;
  overflow: hidden;
  background-color: var(--color-bg-base, #0e1014);
}

/* ==========================================================================
   Full-Bleed Dynamic Backdrop & Google TV Scrim Overlays
   ========================================================================== */
/* Full-bleed crossfaded backdrop image layer */
#bg,
.bg-backdrop {
  position: fixed;
  top: 0;
  left: 0;
  width: 1920px;
  height: 1080px;
  overflow: hidden;
  pointer-events: none;
  z-index: 0;
}

#bg img,
.bg-backdrop img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0;
  transition: opacity 0.9s cubic-bezier(0.2, 0, 0, 1);
  will-change: opacity;
}

#bg img.on,
.bg-backdrop img.on {
  opacity: 1;
}

/* Low-cost blurred backdrop copy (GPU-accelerated filter, activated on scroll) */
#bgBlur,
.bg-blur {
  position: fixed;
  top: -60px;
  left: -60px;
  width: calc(100% + 120px);
  height: calc(100% + 120px);
  object-fit: cover;
  filter: blur(28px) saturate(1.4) brightness(0.7);
  -webkit-filter: blur(28px) saturate(1.4) brightness(0.7);
  opacity: 0;
  transition: opacity 0.35s cubic-bezier(0.2, 0, 0, 1);
  pointer-events: none;
  z-index: 0;
  will-change: opacity;
  transform: translateZ(0);
}

.scrolled #bgBlur,
body.scrolled #bgBlur,
.scrolled .bg-blur,
body.scrolled .bg-blur {
  opacity: 1;
}

/* Dual-gradient Google TV Scrim Overlay (#shade) */
#shade,
.scrim-shade {
  position: fixed;
  top: 0;
  left: 0;
  width: 1920px;
  height: 1080px;
  background:
    linear-gradient(90deg, rgba(14, 16, 20, 0.95) 0%, rgba(14, 16, 20, 0.70) 32%, rgba(14, 16, 20, 0) 62%),
    linear-gradient(0deg, #0e1014 30%, rgba(14, 16, 20, 0.60) 48%, rgba(14, 16, 20, 0) 70%);
  transition: background 0.4s cubic-bezier(0.2, 0, 0, 1);
  pointer-events: none;
  z-index: 1;
}

/* Scrolled scrim state: darkens or blends with blurred backdrop */
.scrolled #shade,
body.scrolled #shade,
.scrolled .scrim-shade,
body.scrolled .scrim-shade {
  background: rgba(14, 16, 20, 0.88);
}

