args.ReplacementContent:
/* ==========================================================================
   Header Container (Fixed Google TV Navigation Bar)
   ========================================================================== */
.app-header {
  position: fixed;
  top: 0;
  left: 0;
  width: var(--canvas-width, 1920px);
  height: var(--header-height);
  padding-left: var(--tv-safe-x);
  padding-right: var(--tv-safe-x);
  display: flex;
  justify-content: space-between;
  align-items: center;
  z-index: 100;
  pointer-events: auto;
  background: linear-gradient(180deg, rgba(14, 16, 20, 0.85) 0%, rgba(14, 16, 20, 0) 100%);
  transition: opacity 0.3s cubic-bezier(0.2, 0, 0, 1), transform 0.3s cubic-bezier(0.2, 0, 0, 1);
  will-change: opacity, transform;
}

/* Auto-hide transition on vertical scroll (Google TV style) */
.scrolled .app-header,
body.scrolled .app-header {
  opacity: 0;
  transform: translateY(-20px);
  pointer-events: none;
}

/* Complete hide when entering video player */
.app-header.header-hidden {
  opacity: 0;
  transform: translateY(-100%);
  pointer-events: none;
}

/* Top Pill Navigation Bar Layout */
.nav-glass-pill,
.header-nav,
.pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-radius: 40px;
  padding: 6px 10px;
}

.pill .tab,
.nav-pill-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 24px;
  border-radius: 30px;
  font-size: var(--font-size-body, 18px);
  text-decoration: none;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, transform 0.15s ease;
}

/* ==========================================================================
   Views Hierarchy & Router Container
   ========================================================================== */
.views-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 1920px;
  height: 1080px;
  overflow: hidden;
  z-index: 2;
}

.view {
  position: absolute;
  top: 0;
  left: 0;
  width: 1920px;
  height: 1080px;
  overflow: hidden;
  display: none;
  opacity: 0;
  transform: scale(0.99);
  transition: opacity 0.28s cubic-bezier(0.2, 0, 0, 1), transform 0.28s cubic-bezier(0.2, 0, 0, 1);
}

.view.active {
  display: block;
  opacity: 1;
  transform: scale(1.0);
}

/* Scrollable View Content Pane */
.view-scroll-pane {
  position: absolute;
  top: 0;
  left: 0;
  width: 1920px;
  height: 1080px;
  overflow-y: scroll;
  overflow-x: hidden;
  scrollbar-width: none;
  -ms-overflow-style: none;
  scroll-behavior: smooth;
  padding-top: var(--header-height);
  padding-bottom: 72px;
  will-change: transform;
}

.view-scroll-pane::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}

/* ==========================================================================
   Grids & Content Shelves
   ========================================================================== */
/* Horizontal Content Shelf */
.content-shelf {
  position: relative;
  margin-top: 36px;
  padding-left: var(--tv-safe-x);
  padding-right: var(--tv-safe-x);
  width: 100%;
}

.shelf-rail {
  display: flex;
  gap: 24px;
  overflow-x: hidden;
  overflow-y: visible;
  padding-top: 20px;
  padding-bottom: 24px;
  padding-left: 4px;
  padding-right: var(--tv-safe-x);
  scroll-behavior: smooth;
  will-change: transform;
}

/* 6-Column Grid Layout for Movies, Series, and Search Results */
.content-grid-6col {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 28px 24px;
  padding-left: var(--tv-safe-x);
  padding-right: var(--tv-safe-x);
  padding-top: 24px;
  padding-bottom: 64px;
  width: 100%;
}

/* Full-Screen Overlay Canvas Lock */
html #details,
html #search,
html #bg,
html #shade,
html #bgBlur {
  width: 1920px;
  height: 1080px;
}

/* Zero Scrollbar Enforcer */
.no-scrollbar {
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.no-scrollbar::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}

