  position: absolute;
  top: 0;
  left: 0;
  width: 1920px;
  height: 1080px;
  overflow: hidden;
}

.view {
  position: absolute;
  top: 0;
  left: 0;
  width: 1920px;
  height: 1080px;
  overflow: hidden;
  display: none;
  opacity: 0;
  transform: scale(0.99);
  transition: opacity 0.28s cubic-bezier(0.2, 0, 0, 1), transform 0.28s cubic-bezier(0.2, 0, 0, 1);
}

.view.active {
  display: block;
  opacity: 1;
  transform: scale(1.0);
}

/* Scrollable View Content Pane */
.view-scroll-pane {
  position: absolute;
  top: 0;
  left: 0;
  width: 1920px;
  height: 1080px;
  overflow-y: scroll;
  overflow-x: hidden;
  scrollbar-width: none;
  -ms-overflow-style: none;
  scroll-behavior: smooth;
  padding-top: var(--header-height);
  padding-bottom: 72px;
}

.view-scroll-pane::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}

/* ==========================================================================
   Grids & Content Shelves
   ========================================================================== */
/* Horizontal Content Shelf */
.content-shelf {
  position: relative;
  margin-top: 36px;
  padding-left: var(--tv-safe-x);
  padding-right: var(--tv-safe-x);
  width: 100%;
}

.shelf-rail {
  display: flex;
  gap: 24px;
  overflow-x: hidden;
  overflow-y: visible;
  padding-top: 20px;
  padding-bottom: 24px;
  padding-left: 4px;
  padding-right: var(--tv-safe-x);
  scroll-behavior: smooth;
}

/* 6-Column Grid Layout for Movies, Series, and Search Results */
.content-grid-6col {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 28px 24px;
  padding-left: var(--tv-safe-x);
  padding-right: var(--tv-safe-x);
  padding-top: 24px;
  padding-bottom: 64px;
  width: 100%;
}

/* Zero Scrollbar Enforcer */
.no-scrollbar {
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.no-scrollbar::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}

